#!/usr/bin/env python3
"""Writes docs/COMMANDS.md from the command registry.

Usage: python3 scripts/gen_commands.py <path to the mesh2cad executable>
"""
import json
import subprocess
import sys
from pathlib import Path


def main() -> int:
    if len(sys.argv) != 2:
        print(__doc__)
        return 2
    out = subprocess.run([sys.argv[1], "list"], capture_output=True, text=True, check=True).stdout
    commands = json.loads(out)["result"]["commands"]
    lines = [
        "# Commands",
        "",
        "Generated by `scripts/gen_commands.py` from the registry; do not edit by hand.",
        "Every command works the same from the desktop app (Tools menu), `mesh2cad run`/`batch`,",
        "JSON-RPC (`mesh2cad-rpc` or the app's local socket) and MCP (`mesh2cad-mcp`, where dots",
        "become underscores: `mesh.repair` is the tool `mesh_repair`).",
        "",
        "Lengths are millimetres; objects are referred to by id (see `doc.list`).",
        "",
    ]
    groups: dict[str, list] = {}
    for c in commands:
        groups.setdefault(c["name"].split(".")[0], []).append(c)
    for group, items in groups.items():
        lines += [f"## {group}", ""]
        for c in items:
            if c.get("mutates_document"):
                kind = "changes the document"
            elif c.get("writes_files"):
                kind = "writes a file"
            else:
                kind = "read-only"
            lines += [f"### `{c['name']}`", "", f"{c['summary']} *({kind})*", ""]
            schema = c.get("params_schema", {})
            props = schema.get("properties", {})
            required = set(schema.get("required", []))
            if props:
                lines += ["| Parameter | Type | Required | Notes |", "| --- | --- | --- | --- |"]
                for key, p in props.items():
                    ptype = p.get("type", "")
                    if "enum" in p:
                        ptype = " \\| ".join(f"`{v}`" for v in p["enum"])
                    if "x-object" in p:
                        kinds = p["x-object"] if isinstance(p["x-object"], list) else [p["x-object"]]
                        ptype = " or ".join("object" if k == "any" else k for k in kinds) + " id"
                    notes = p.get("description", "")
                    if "default" in p:
                        notes = (notes + " " if notes else "") + f"Default `{json.dumps(p['default'])}`."
                    notes = notes.replace("|", "\\|")
                    lines.append(f"| `{key}` | {ptype} | {'yes' if key in required else ''} | {notes} |")
                lines.append("")
    Path(__file__).resolve().parent.parent.joinpath("docs", "COMMANDS.md").write_text(
        "\n".join(lines), encoding="utf-8")
    print(f"wrote docs/COMMANDS.md ({len(commands)} commands)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
